/**
 * Browser/Node research election protocol. This executes locally, NOT on Midnight.
 * Keys are generated by one demo dealer, not a distributed key ceremony.
 * Voter credentials are pseudonymous public keys, not anonymous ZK credentials.
 * No claims of receipt-freeness, coercion resistance, or production readiness.
 */
import {
  GROUP_ID, P, Q, G, mod, pow, inverse, hex, scalar, element,
  objectKeys, requireCondition, canonical, hash, randomScalar,
  proveDLEQ, verifyDLEQ, proveBit, verifyBit, sign, verifySignature,
  lagrangeAtZero, boundedDiscreteLog,
} from './crypto.mjs';

export const SCHEMAS = Object.freeze({
  manifest: 'ballot-lab/manifest/v1', ballot: 'ballot-lab/ballot/v1',
  share: 'ballot-lab/decryption-share/v1', record: 'ballot-lab/record/v1',
  receipt: 'ballot-lab/receipt/v1',
});
const MANIFEST_KEYS = ['schema', 'group', 'electionId', 'title', 'candidates', 'maxBallots', 'threshold', 'trustees', 'voterPublicKeys', 'keyCommitments'];
const BALLOT_KEYS = ['schema', 'electionHash', 'nullifier', 'voterPublicKey', 'ciphertexts', 'bitProofs', 'sumProof', 'signature', 'id'];
const HASH_RE = /^[0-9a-f]{64}$/;
const copy = value => JSON.parse(JSON.stringify(value));
const errorText = error => error instanceof Error ? error.message : String(error);

function text(value, label, min = 1, max = 160) {
  requireCondition(typeof value === 'string' && value.length >= min && value.length <= max && value === value.trim(), `${label}: invalid text`);
  requireCondition(!/[\u0000-\u001f\u007f]/.test(value), `${label}: control characters are forbidden`);
}
function digest(value, label) { requireCondition(typeof value === 'string' && HASH_RE.test(value), `${label}: invalid SHA-256 digest`); }
function integer(value, min, max, label) { requireCondition(Number.isSafeInteger(value) && value >= min && value <= max && !Object.is(value, -0), `${label}: invalid integer`); }
function vector(value, length, label) { requireCondition(Array.isArray(value) && value.length === length, `${label}: invalid vector length`); }

export function validateManifest(manifest) {
  objectKeys(manifest, MANIFEST_KEYS, 'Manifest');
  requireCondition(manifest.schema === SCHEMAS.manifest && manifest.group === GROUP_ID, 'Unsupported manifest schema or cryptographic group');
  text(manifest.electionId, 'Election ID', 1, 128); text(manifest.title, 'Election title');
  requireCondition(Array.isArray(manifest.candidates), 'Candidates must be an array');
  integer(manifest.candidates.length, 2, 5, 'Candidate count');
  manifest.candidates.forEach(c => text(c, 'Candidate label', 1, 80));
  requireCondition(new Set(manifest.candidates).size === manifest.candidates.length, 'Candidate labels must be unique');
  integer(manifest.maxBallots, 1, 1000, 'Maximum ballots');
  requireCondition(manifest.threshold === 2, 'This prototype requires a 2-of-3 threshold');
  vector(manifest.keyCommitments, 2, 'Key commitments');
  const commitments = manifest.keyCommitments.map((v, i) => element(v, `Key commitment ${i}`, true));
  vector(manifest.trustees, 3, 'Trustees');
  manifest.trustees.forEach((trustee, i) => {
    objectKeys(trustee, ['index', 'publicKey'], 'Trustee');
    requireCondition(trustee.index === i + 1, 'Trustee indices must be exactly 1, 2, 3');
    const publicKey = element(trustee.publicKey, 'Trustee public key', true);
    requireCondition(publicKey === mod(commitments[0] * pow(commitments[1], BigInt(trustee.index))), 'Trustee key is inconsistent with threshold commitments');
  });
  requireCondition(new Set(manifest.trustees.map(t => t.publicKey)).size === 3, 'Trustee keys must be distinct');
  requireCondition(Array.isArray(manifest.voterPublicKeys), 'Voter keys must be an array');
  integer(manifest.voterPublicKeys.length, 1, manifest.maxBallots, 'Voter count');
  requireCondition(new Set(manifest.voterPublicKeys).size === manifest.voterPublicKeys.length, 'Duplicate eligible voter credentials');
  manifest.voterPublicKeys.forEach(key => element(key, 'Voter public key', true));
  return manifest;
}

export async function hashManifest(manifest) {
  validateManifest(manifest);
  return hash('election-manifest', manifest);
}
export async function hashRecord(record) { return hash('final-election-record', record); }

/** Centralized demo dealer. All returned secrets belong outside public records. */
export async function setupElection({ id = globalThis.crypto.randomUUID(), title = 'Ballot Lab demonstration', candidates = ['Candidate A', 'Candidate B', 'Candidate C'], maxBallots = 1000, voterCount = 8 } = {}) {
  integer(maxBallots, 1, 1000, 'Maximum ballots');
  integer(voterCount, 1, maxBallots, 'Voter count');
  const secret = randomScalar(true);
  let slope, shares;
  do {
    slope = randomScalar(true);
    shares = [1, 2, 3].map(index => mod(secret + slope * BigInt(index), Q));
  } while (shares.some(share => share === 0n));
  const trustees = shares.map((secretShare, i) => ({ index: i + 1, secretShare: hex(secretShare), publicKey: hex(pow(G, secretShare)) }));
  const credentials = [];
  const seen = new Set();
  for (let i = 0; i < voterCount; i++) {
    let sk, publicKey;
    do { sk = randomScalar(true); publicKey = hex(pow(G, sk)); } while (seen.has(publicKey));
    seen.add(publicKey);
    credentials.push({ alias: `Demo voter ${String(i + 1).padStart(2, '0')}`, publicKey, secretKey: hex(sk) });
  }
  const manifest = {
    schema: SCHEMAS.manifest, group: GROUP_ID, electionId: id, title,
    candidates: [...candidates], maxBallots, threshold: 2,
    trustees: trustees.map(({ index, publicKey }) => ({ index, publicKey })),
    voterPublicKeys: credentials.map(c => c.publicKey),
    keyCommitments: [hex(pow(G, secret)), hex(pow(G, slope))],
  };
  validateManifest(manifest);
  return { manifest, trustees, credentials };
}

function ballotContext(electionHash, nullifier, voterPublicKey) { return { electionHash, nullifier, voterPublicKey }; }
function unsignedBallot(ballot) {
  const { signature, id, ...unsigned } = ballot;
  return unsigned;
}
async function ballotDigest(ballot) { const { id, ...body } = ballot; return hash('ballot-receipt', body); }
function readCiphertexts(ciphertexts, length, allowIdentity = false) {
  vector(ciphertexts, length, 'Ciphertexts');
  return ciphertexts.map((ciphertext, i) => {
    objectKeys(ciphertext, ['a', 'b'], 'Ciphertext');
    return { a: element(ciphertext.a, `Ciphertext ${i} a`, !allowIdentity), b: element(ciphertext.b, `Ciphertext ${i} b`) };
  });
}

export async function encryptBallot(manifest, candidateIndex, credential) {
  const electionHash = await hashManifest(manifest);
  integer(candidateIndex, 0, manifest.candidates.length - 1, 'Selected candidate');
  requireCondition(credential && typeof credential === 'object', 'A demo voter credential is required');
  const secret = scalar(credential.secretKey, 'Voter secret', true);
  const voterPublicKey = credential.publicKey;
  const publicKey = element(voterPublicKey, 'Voter public key', true);
  requireCondition(manifest.voterPublicKeys.includes(voterPublicKey), 'Credential is not eligible for this election');
  requireCondition(pow(G, secret) === publicKey, 'Credential public and secret keys do not match');
  const y = element(manifest.keyCommitments[0]);
  const nullifier = await hash('credential-nullifier', electionHash, voterPublicKey);
  const context = ballotContext(electionHash, nullifier, voterPublicKey);
  const ciphertexts = [], bitProofs = [];
  let sumRandomness = 0n, sumA = 1n, sumB = 1n;
  for (let i = 0; i < manifest.candidates.length; i++) {
    const r = randomScalar(true), bit = i === candidateIndex ? 1 : 0;
    const a = pow(G, r), b = mod(pow(y, r) * pow(G, BigInt(bit)));
    ciphertexts.push({ a: hex(a), b: hex(b) });
    bitProofs.push(await proveBit({ ...context, candidateIndex: i }, y, a, b, bit, r));
    sumRandomness = mod(sumRandomness + r, Q); sumA = mod(sumA * a); sumB = mod(sumB * b);
  }
  const sumProof = await proveDLEQ('one-selection', { ...context, ciphertexts }, y, sumA, mod(sumB * inverse(G)), sumRandomness);
  const body = { schema: SCHEMAS.ballot, electionHash, nullifier, voterPublicKey, ciphertexts, bitProofs, sumProof };
  const signature = await sign(await hash('signed-ballot', body), publicKey, secret);
  const ballot = { ...body, signature };
  return { ...ballot, id: await ballotDigest(ballot) };
}

async function assertBallot(manifest, electionHash, ballot) {
  objectKeys(ballot, BALLOT_KEYS, 'Ballot');
  requireCondition(ballot.schema === SCHEMAS.ballot, 'Unsupported ballot schema');
  digest(ballot.id, 'Ballot ID'); digest(ballot.electionHash, 'Ballot election hash'); digest(ballot.nullifier, 'Ballot nullifier');
  requireCondition(ballot.electionHash === electionHash, 'Ballot belongs to a different election');
  requireCondition(manifest.voterPublicKeys.includes(ballot.voterPublicKey), 'Ballot credential is not eligible');
  const publicKey = element(ballot.voterPublicKey, 'Voter public key', true);
  requireCondition(ballot.nullifier === await hash('credential-nullifier', electionHash, ballot.voterPublicKey), 'Invalid election-scoped nullifier');
  requireCondition(ballot.id === await ballotDigest(ballot), 'Ballot fingerprint does not match content');
  await verifySignature(await hash('signed-ballot', unsignedBallot(ballot)), publicKey, ballot.signature);
  const ciphertexts = readCiphertexts(ballot.ciphertexts, manifest.candidates.length);
  vector(ballot.bitProofs, manifest.candidates.length, 'Ballot bit proofs');
  const context = ballotContext(electionHash, ballot.nullifier, ballot.voterPublicKey);
  const y = element(manifest.keyCommitments[0]);
  let sumA = 1n, sumB = 1n;
  for (let i = 0; i < ciphertexts.length; i++) {
    const { a, b } = ciphertexts[i];
    await verifyBit({ ...context, candidateIndex: i }, y, a, b, ballot.bitProofs[i]);
    sumA = mod(sumA * a); sumB = mod(sumB * b);
  }
  await verifyDLEQ('one-selection', { ...context, ciphertexts: ballot.ciphertexts }, y, sumA, mod(sumB * inverse(G)), ballot.sumProof);
  return ciphertexts;
}

export async function verifyBallot(manifest, ballot) {
  try { await assertBallot(manifest, await hashManifest(manifest), ballot); return { valid: true, errors: [] }; }
  catch (error) { return { valid: false, errors: [errorText(error)] }; }
}

export async function aggregateBallots(manifest, ballots) {
  const electionHash = await hashManifest(manifest);
  requireCondition(Array.isArray(ballots) && ballots.length <= manifest.maxBallots, 'Invalid or oversized ballot list');
  const ids = new Set(), nullifiers = new Set();
  const products = manifest.candidates.map(() => ({ a: 1n, b: 1n }));
  for (const ballot of ballots) {
    const ciphertexts = await assertBallot(manifest, electionHash, ballot);
    requireCondition(!ids.has(ballot.id), 'Duplicate ballot fingerprint');
    requireCondition(!nullifiers.has(ballot.nullifier), 'Duplicate voter credential/nullifier');
    ids.add(ballot.id); nullifiers.add(ballot.nullifier);
    ciphertexts.forEach(({ a, b }, i) => { products[i].a = mod(products[i].a * a); products[i].b = mod(products[i].b * b); });
  }
  return {
    electionHash,
    ballotSetHash: await hash('accepted-ballot-set', electionHash, [...ids].sort()),
    count: ballots.length,
    ciphertexts: products.map(({ a, b }) => ({ a: hex(a), b: hex(b) })),
  };
}

function shareContext(aggregate, trusteeIndex, candidateIndex) { return { aggregate, trusteeIndex, candidateIndex }; }

export async function createDecryptionShare(manifest, ballots, trustee) {
  const aggregate = await aggregateBallots(manifest, ballots);
  requireCondition(trustee && typeof trustee === 'object', 'Trustee secret is required');
  integer(trustee.index, 1, 3, 'Trustee index');
  const registered = manifest.trustees[trustee.index - 1];
  requireCondition(trustee.publicKey === registered.publicKey, 'Trustee is not registered');
  const secret = scalar(trustee.secretShare, 'Trustee secret share', true);
  const publicKey = element(registered.publicKey, 'Trustee public key', true);
  requireCondition(pow(G, secret) === publicKey, 'Trustee secret share does not match public key');
  const values = [];
  for (let i = 0; i < aggregate.ciphertexts.length; i++) {
    const a = element(aggregate.ciphertexts[i].a), d = pow(a, secret);
    values.push({ value: hex(d), proof: await proveDLEQ('threshold-share', shareContext(aggregate, trustee.index, i), a, publicKey, d, secret) });
  }
  return { schema: SCHEMAS.share, electionHash: aggregate.electionHash, ballotSetHash: aggregate.ballotSetHash, trusteeIndex: trustee.index, values };
}

async function assertShare(manifest, aggregate, share) {
  objectKeys(share, ['schema', 'electionHash', 'ballotSetHash', 'trusteeIndex', 'values'], 'Decryption share');
  requireCondition(share.schema === SCHEMAS.share, 'Unsupported decryption-share schema');
  requireCondition(share.electionHash === aggregate.electionHash && share.ballotSetHash === aggregate.ballotSetHash, 'Decryption share is for another election or ballot set');
  integer(share.trusteeIndex, 1, 3, 'Trustee index');
  const publicKey = element(manifest.trustees[share.trusteeIndex - 1].publicKey, 'Trustee public key', true);
  vector(share.values, manifest.candidates.length, 'Decryption share values');
  for (let i = 0; i < share.values.length; i++) {
    objectKeys(share.values[i], ['value', 'proof'], 'Partial decryption');
    const d = element(share.values[i].value, 'Partial decryption');
    const a = element(aggregate.ciphertexts[i].a);
    await verifyDLEQ('threshold-share', shareContext(aggregate, share.trusteeIndex, i), a, publicKey, d, share.values[i].proof);
  }
}

export async function verifyDecryptionShare(manifest, aggregate, share) {
  try {
    validateManifest(manifest);
    objectKeys(aggregate, ['electionHash', 'ballotSetHash', 'count', 'ciphertexts'], 'Aggregate');
    requireCondition(aggregate.electionHash === await hashManifest(manifest), 'Aggregate election mismatch');
    digest(aggregate.ballotSetHash, 'Ballot-set digest'); integer(aggregate.count, 0, manifest.maxBallots, 'Aggregate count');
    readCiphertexts(aggregate.ciphertexts, manifest.candidates.length, true);
    await assertShare(manifest, aggregate, share);
    return { valid: true, errors: [] };
  } catch (error) { return { valid: false, errors: [errorText(error)] }; }
}

async function decryptAggregate(manifest, aggregate, shares) {
  requireCondition(Array.isArray(shares) && shares.length >= manifest.threshold && shares.length <= 3, 'Two or three distinct trustee shares are required');
  const indices = shares.map(s => s?.trusteeIndex);
  requireCondition(new Set(indices).size === shares.length, 'Duplicate trustee shares');
  for (const share of shares) await assertShare(manifest, aggregate, share);
  const tally = [];
  for (let i = 0; i < manifest.candidates.length; i++) {
    let decryption = 1n;
    for (const share of shares) decryption = mod(decryption * pow(element(share.values[i].value), lagrangeAtZero(share.trusteeIndex, indices)));
    const plaintext = mod(element(aggregate.ciphertexts[i].b) * inverse(decryption));
    tally.push(boundedDiscreteLog(plaintext, aggregate.count));
  }
  requireCondition(tally.reduce((a, b) => a + b, 0) === aggregate.count, 'Tally does not equal the number of accepted ballots');
  return tally;
}

export async function finalizeElection(manifest, ballots, shares) {
  const aggregate = await aggregateBallots(manifest, ballots);
  const tally = await decryptAggregate(manifest, aggregate, shares);
  return copy({ schema: SCHEMAS.record, manifest, manifestHash: aggregate.electionHash, ballots, aggregate, shares: [...shares].sort((a, b) => a.trusteeIndex - b.trusteeIndex), tally });
}

export async function verifyElectionRecord(record, options = {}) {
  const result = { valid: false, anchored: false, manifestAnchored: false, recordAnchored: false, checks: [], errors: [], warnings: [], tally: null, ballotCount: 0, manifestHash: null, recordHash: null };
  const check = name => result.checks.push({ name, valid: true });
  try {
    requireCondition(options && typeof options === 'object' && !Array.isArray(options), 'Invalid verification options');
    requireCondition(Object.keys(options).every(k => ['expectedManifestHash', 'expectedRecordHash'].includes(k)), 'Unknown verification option');
    objectKeys(record, ['schema', 'manifest', 'manifestHash', 'ballots', 'aggregate', 'shares', 'tally'], 'Election record');
    requireCondition(record.schema === SCHEMAS.record, 'Unsupported election-record schema');
    result.manifestHash = await hashManifest(record.manifest);
    requireCondition(record.manifestHash === result.manifestHash, 'Manifest fingerprint mismatch');
    if (options.expectedManifestHash !== undefined) {
      digest(options.expectedManifestHash, 'Expected election fingerprint');
      requireCondition(options.expectedManifestHash === result.manifestHash, 'Election does not match the independently trusted manifest fingerprint');
      result.manifestAnchored = true;
    }
    check('Election rules and threshold public keys are consistent');
    const aggregate = await aggregateBallots(record.manifest, record.ballots);
    result.ballotCount = aggregate.count;
    check('All ballot signatures, eligibility entries and zero-knowledge proofs are valid');
    check('Each pseudonymous credential contributes at most one accepted ballot');
    objectKeys(record.aggregate, ['electionHash', 'ballotSetHash', 'count', 'ciphertexts'], 'Recorded aggregate');
    requireCondition(canonical(record.aggregate) === canonical(aggregate), 'Published encrypted aggregate does not match all accepted ballots');
    check('Encrypted aggregate matches the complete published ballot set');
    const tally = await decryptAggregate(record.manifest, aggregate, record.shares);
    vector(record.tally, record.manifest.candidates.length, 'Published tally');
    record.tally.forEach(v => integer(v, 0, aggregate.count, 'Candidate total'));
    requireCondition(canonical(tally) === canonical(record.tally), 'Published tally does not match verified threshold decryption');
    check('Threshold decryption proofs and final totals are correct');
    result.tally = tally;
    result.recordHash = await hashRecord(record);
    if (options.expectedRecordHash !== undefined) {
      digest(options.expectedRecordHash, 'Expected final-record fingerprint');
      requireCondition(options.expectedRecordHash === result.recordHash, 'Record does not match the independently trusted final-record fingerprint');
      result.recordAnchored = true;
    }
    result.anchored = result.manifestAnchored && result.recordAnchored;
    if (!result.manifestAnchored) result.warnings.push('No independently trusted election fingerprint was supplied; the verifier cannot authenticate the election definition.');
    if (!result.recordAnchored) result.warnings.push('No independently trusted final-record fingerprint was supplied; this check cannot establish completeness relative to an external bulletin board.');
    result.warnings.push('Local research protocol only: no Midnight ledger inclusion or national-election security is established.');
    result.valid = true;
  } catch (error) {
    result.errors.push(errorText(error));
    result.checks.push({ name: errorText(error), valid: false });
  }
  return result;
}

export async function receiptForBallot(manifest, ballot) {
  const electionHash = await hashManifest(manifest);
  await assertBallot(manifest, electionHash, ballot);
  return { schema: SCHEMAS.receipt, electionId: manifest.electionId, electionHash, ballotId: ballot.id };
}

export async function verifyReceipt(record, receipt, options = {}) {
  try {
    objectKeys(receipt, ['schema', 'electionId', 'electionHash', 'ballotId'], 'Receipt');
    requireCondition(receipt.schema === SCHEMAS.receipt, 'Unsupported receipt schema');
    digest(receipt.electionHash, 'Receipt election fingerprint'); digest(receipt.ballotId, 'Receipt ballot fingerprint');
    const verification = await verifyElectionRecord(record, options);
    requireCondition(verification.valid, verification.errors.join('; '));
    requireCondition(receipt.electionId === record.manifest.electionId && receipt.electionHash === verification.manifestHash, 'Receipt belongs to another election');
    const included = record.ballots.some(ballot => ballot.id === receipt.ballotId);
    requireCondition(included, 'Receipt ballot is absent from the verified final record');
    return { valid: true, included: true, errors: [], anchored: verification.anchored, warnings: verification.warnings };
  } catch (error) { return { valid: false, included: false, errors: [errorText(error)], anchored: false }; }
}
